pragma solidity ^0.8.16;

import "./BabyJubJub.sol";
import "../Types.sol";

contract ElGamalEncryption {
    function add(
        ElGamalCiphertext memory ct1,
        ElGamalCiphertext memory ct2
    ) external view returns (ElGamalCiphertext memory ct3) {
